"""The game material library: original procedural materials, generated by code in Blender's runner, nothing downloaded.

A region of a cage (or a material zone of a CAD design) takes one material:

    {"material": "painted_metal", "tint": "#3f5a4a", "grain_mm": 30, "wear": 0.6}

    material   one of KINDS: wood, bare_metal, brushed_metal, painted_metal, leather, plastic, rubber, stone, fabric,
               emissive. Each sets a base colour, roughness, metallic and a height pattern (baked into the normal map).
    tint       #rrggbb, the base colour (default: the kind's own)
    grain_mm   the pattern's size in millimetres (wood grain, brush lines, leather pebbles, stone cells, weave)
    wear       0..1, how much the edges wear through (painted metal shows bare metal, wood and leather lighten) and how
               much dirt sits in cavities; masks come from the high-poly (curvature, AO, thickness), baked in Blender
    roughness  0..1, overrides the kind's roughness
    emission   0..50, emission strength (the emissive kind defaults to 4; others 0)
    label      a name for the report

The older form {"finish", "color", "pattern", "pattern_mm"} is still read: a finish and pattern pick the nearest kind
(legacy()), so briefs and calls written for the first runner keep working.

A design keeps its materials in its source, like appearance(): a materials() method that returns a literal dict
{region or zone or "default": material}. materials_in_source() reads it with ast.literal_eval, never running the
source. Plain Python, no Blender: the engine, MCP server and tests import it freely.
"""
from __future__ import annotations

import ast
import math
import re

HEX = re.compile(r"#[0-9a-fA-F]{6}")
KEYS = {"material", "tint", "grain_mm", "wear", "roughness", "emission", "label", "features",
        # the first runner's form, still read (legacy())
        "finish", "color", "pattern", "pattern_mm"}
LEGACY_PATTERNS = ("none", "wood", "noise", "brushed")

# Every kind: default tint, roughness, metallic, pattern size (mm), relief (the bump depth baked into the normal map,
# as a share of the pattern size, so the slope reads the same at any grain), the default wear, what a worn edge shows (colour, roughness, metallic; "lighten" lifts the tint)
# and the colour of cavity dirt. Values are art choices for a stylised-realistic prop, not measured material data.
KINDS = {
    "wood": {"label": "Wood", "tint": "#8a5a32", "roughness": 0.62, "metallic": 0.0, "grain_mm": 60.0,
             "relief": 0.025, "wear": 0.5, "edge": "lighten", "edge_roughness": 0.5, "edge_metallic": 0.0,
             "dirt": "#2a1c12"},
    "bare_metal": {"label": "Bare metal", "tint": "#8d9196", "roughness": 0.38, "metallic": 1.0, "grain_mm": 12.0,
                   "relief": 0.012, "wear": 0.4, "edge": "#d5d8dc", "edge_roughness": 0.22, "edge_metallic": 1.0,
                   "dirt": "#2b2a28"},
    "brushed_metal": {"label": "Brushed metal", "tint": "#a9aeb4", "roughness": 0.3, "metallic": 1.0, "grain_mm": 25.0,
                      "relief": 0.006, "wear": 0.35, "edge": "#e0e3e6", "edge_roughness": 0.18, "edge_metallic": 1.0,
                      "dirt": "#30302e"},
    "painted_metal": {"label": "Painted metal", "tint": "#4a6a58", "roughness": 0.5, "metallic": 0.0, "grain_mm": 18.0,
                      "relief": 0.015, "wear": 0.55, "edge": "#9a9ea3", "edge_roughness": 0.3,
                      "edge_metallic": 1.0, "dirt": "#2a2622"},
    "leather": {"label": "Leather", "tint": "#5a3622", "roughness": 0.55, "metallic": 0.0, "grain_mm": 3.0,
                "relief": 0.08, "wear": 0.45, "edge": "lighten", "edge_roughness": 0.4, "edge_metallic": 0.0,
                "dirt": "#1d130c"},
    "plastic": {"label": "Plastic", "tint": "#2c2f33", "roughness": 0.42, "metallic": 0.0, "grain_mm": 4.0,
                "relief": 0.012, "wear": 0.3, "edge": "lighten", "edge_roughness": 0.3, "edge_metallic": 0.0,
                "dirt": "#18191a"},
    "rubber": {"label": "Rubber", "tint": "#262626", "roughness": 0.85, "metallic": 0.0, "grain_mm": 6.0,
               "relief": 0.05, "wear": 0.3, "edge": "lighten", "edge_roughness": 0.7, "edge_metallic": 0.0,
               "dirt": "#3a352e"},
    "stone": {"label": "Stone", "tint": "#7d7a74", "roughness": 0.8, "metallic": 0.0, "grain_mm": 80.0,
              "relief": 0.035, "wear": 0.5, "edge": "lighten", "edge_roughness": 0.7, "edge_metallic": 0.0,
              "dirt": "#2e2b27"},
    "fabric": {"label": "Fabric", "tint": "#6b5b45", "roughness": 0.9, "metallic": 0.0, "grain_mm": 2.5,
               "relief": 0.06, "wear": 0.35, "edge": "lighten", "edge_roughness": 0.85, "edge_metallic": 0.0,
               "dirt": "#2a241c"},
    "emissive": {"label": "Emissive", "tint": "#7fd6ff", "roughness": 0.3, "metallic": 0.0, "grain_mm": 10.0,
                 "relief": 0.0, "wear": 0.0, "edge": "lighten", "edge_roughness": 0.3, "edge_metallic": 0.0,
                 "dirt": "#101214", "emission": 4.0},
}
DEFAULT = {"material": "plastic", "tint": "#b8b2a7"}


class MaterialError(ValueError):
    def __init__(self, message, hint=""):
        super().__init__(message)
        self.hint = hint


def srgb_to_linear(hexcol: str) -> list[float]:
    out = []
    for i in (1, 3, 5):
        c = int(hexcol[i:i + 2], 16) / 255
        out.append(round(c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4, 6))
    return out


def _num(name, key, x, lo, hi):
    if isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(float(x)) or not lo <= x <= hi:
        raise MaterialError(f"material {name}: {key} must be a number from {lo:g} to {hi:g}.")
    return float(x)


def legacy(m: dict) -> dict:
    """The first runner's {finish, color, pattern, pattern_mm} as a library material: metal finishes become bare or
    brushed metal, rubber stays rubber, a wood pattern becomes wood, every other finish plastic."""
    fin = str(m.get("finish") or "matte")
    pat = str(m.get("pattern") or "none")
    if fin == "metal" or fin == "silk":
        kind = "brushed_metal" if pat == "brushed" else "bare_metal"
    elif fin == "rubber":
        kind = "rubber"
    elif pat == "wood":
        kind = "wood"
    elif fin == "carbon":
        kind = "fabric"
    else:
        kind = "plastic"
    out = {"material": kind}
    if m.get("color") is not None:
        out["tint"] = m["color"]
    if m.get("pattern_mm") is not None:
        out["grain_mm"] = m["pattern_mm"]
    if fin in ("gloss", "petg", "smoke") and kind == "plastic":
        out["roughness"] = 0.2
    if pat == "none" and kind not in ("wood",):
        out["wear"] = min(KINDS[kind]["wear"], 0.3)
    return out


def spec(name: str, m) -> dict:
    """A material for the runner: every value a number or a name from KINDS. Raises MaterialError naming what is
    wrong. Reads both the library form and the first runner's form (legacy())."""
    from .presets import safe_name
    if not isinstance(m, dict):
        raise MaterialError(f"material {name} must be an object such as {{\"material\": \"wood\", \"tint\": "
                            "\"#8a5a32\"}.", "Kinds: " + ", ".join(KINDS))
    extra = set(m) - KEYS
    if extra:
        raise MaterialError(f"material {name} does not take {', '.join(sorted(extra))}.",
                            "Keys: material, tint, grain_mm, wear, roughness, emission, label.")
    old = {}
    if "material" not in m and ({"finish", "pattern", "color", "pattern_mm"} & set(m)):
        from ..adapters.blender import FINISHES
        fin = str(m.get("finish") or "matte")
        if fin not in FINISHES:
            raise MaterialError(f"material {name}: unknown finish {fin!r}.", "Finishes: " + ", ".join(FINISHES))
        pat = str(m.get("pattern") or "none")
        if pat not in LEGACY_PATTERNS:
            raise MaterialError(f"material {name}: pattern must be one of {', '.join(LEGACY_PATTERNS)}.")
        col = m.get("color")
        if col is not None and not HEX.fullmatch(str(col)):
            raise MaterialError(f"material {name}: colour {col!r} is not #rrggbb.")
        if m.get("pattern_mm") is not None:
            _num(name, "pattern_mm", m["pattern_mm"], 0.01, 1e5)
        old = {"finish": fin, "pattern": pat}
        m = {**legacy(m), **{k: m[k] for k in ("label",) if k in m}}
    kind = str(m.get("material") or DEFAULT["material"])
    if kind not in KINDS:
        raise MaterialError(f"material {name}: unknown material {kind!r}.", "Kinds: " + ", ".join(KINDS))
    k = KINDS[kind]
    tint = str(m.get("tint") or k["tint"])
    if not HEX.fullmatch(tint):
        raise MaterialError(f"material {name}: tint {tint!r} is not #rrggbb.")
    grain = _num(name, "grain_mm", m.get("grain_mm", k["grain_mm"]), 0.05, 1e5)
    wear = _num(name, "wear", m.get("wear", k["wear"]), 0.0, 1.0)
    rough = _num(name, "roughness", m.get("roughness", k["roughness"]), 0.0, 1.0)
    emis = _num(name, "emission", m.get("emission", k.get("emission", 0.0)), 0.0, 50.0)
    col = srgb_to_linear(tint)
    if k["edge"] == "lighten":
        edge = [round(min(c * 1.9 + 0.03, 1.0), 6) for c in col]
    else:
        edge = srgb_to_linear(k["edge"])
    return {"name": safe_name(name), "kind": kind, "label": str(m.get("label") or k["label"])[:60],
            "hex": tint.lower(), "color": col, "roughness": rough, "metallic": float(k["metallic"]),
            "grain_mm": grain, "height_mm": round(min(float(k["relief"]) * grain, 50.0), 5), "wear": wear,
            "edge_color": edge,
            "edge_roughness": float(k["edge_roughness"]), "edge_metallic": float(k["edge_metallic"]),
            "dirt_color": srgb_to_linear(k["dirt"]), "emission": emis,
            # what the report and the older callers read
            "finish": old.get("finish") or kind, "pattern": old.get("pattern") or kind}


RUNNER_KEYS = ("name", "kind", "color", "roughness", "metallic", "grain_mm", "height_mm", "wear", "edge_color",
               "edge_roughness", "edge_metallic", "dirt_color", "emission")


def for_runner(s: dict) -> dict:
    return {k: s[k] for k in RUNNER_KEYS}


def library() -> list[dict]:
    """The kinds as the app and the MCP tool list them."""
    return [{"id": k, "label": v["label"], "tint": v["tint"], "roughness": v["roughness"], "metallic": v["metallic"],
             "grain_mm": v["grain_mm"], "wear": v["wear"], "emission": v.get("emission", 0.0)}
            for k, v in KINDS.items()]


def check_map(materials) -> dict | None:
    """None, or a {name: material} dict checked by spec(). Raises MaterialError (a list, a string...)."""
    if materials is None:
        return None
    if not isinstance(materials, dict):
        raise MaterialError("materials must be an object mapping region names (or \"default\") to a material, "
                            f"not a {type(materials).__name__}.",
                            "For example {\"default\": {\"material\": \"wood\"}, \"bands\": {\"material\": "
                            "\"painted_metal\"}}.")
    for k, v in materials.items():
        if not isinstance(k, str) or not k:
            raise MaterialError("material names must be non-empty strings.")
        spec(k, v)
    return materials


def materials_in_source(text: str) -> tuple[dict | None, str]:
    """(materials, note) from a design's source: the literal dict a materials() method returns (or a module-level
    MATERIALS = {...}), read with ast.literal_eval and never executed. (None, why) when there is none or it is not a
    plain literal."""
    try:
        tree = ast.parse(text or "")
    except SyntaxError:
        return None, ""
    found = None
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.name == "materials":
            body = [b for b in node.body if not (isinstance(b, ast.Expr) and isinstance(b.value, ast.Constant))]
            if len(body) == 1 and isinstance(body[0], ast.Return) and body[0].value is not None:
                found = body[0].value
            else:
                return None, "materials() is not a single `return {...}` of a literal dict, so it was not read."
            break
    if found is None:
        for node in tree.body:
            if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == "MATERIALS"
                                                    for t in node.targets):
                found = node.value
    if found is None:
        return None, ""
    try:
        val = ast.literal_eval(found)
    except (ValueError, TypeError, SyntaxError):
        return None, "materials() returns something other than a literal dict, so it was not read."
    if not isinstance(val, dict):
        return None, "materials() must return a dict {region or \"default\": material}."
    try:
        check_map(val)
    except MaterialError as e:
        return None, f"materials() in the source was not used: {e}"
    return val, ""


def source_method(materials: dict) -> str:
    """The materials() method written into a design's source (a literal, read back by materials_in_source)."""
    import pprint
    body = pprint.pformat(materials, indent=1, width=100, sort_dicts=True).replace("\n", "\n" + " " * 15)
    return ("    def materials(self, v=None):\n"
            "        \"\"\"Game materials by region (form/game/materials.py), read without running this source.\"\"\"\n"
            f"        return {body}\n")
